 fn requires_original_birth(&self)->bool{if self.close_route.is_some(){return false}if !self.close.is_empty(){self.close.requires_original_birth()}else if self.bytes.is_some()||self.output.is_some(){false}else{RetainedCloneBinding::requires_original_birth(&self.source)}}
