 fn close_into<'reply>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing{return Err(ValueError::invariant("cursor must begin close"))}if self.requires_original_birth()||self.requires_original_control(){return Err(ValueError::invariant("cursor requires selected original close"))}if !self.close.is_empty(){let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),1,body,None);let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=state.close.step_into(body,effect,scope.borrow()?)?;drop(done);return Ok(scope.forwarded())}if self.bytes.is_some(){let state=self;let turn=state.close.begin_granted(&mut state.bytes,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))}if self.output.is_some(){let state=self;let turn=state.close.begin_granted(&mut state.output,effect);return Ok(reply.complete(turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)))} let invocation=effect.invocation().ok_or_else(||ValueError::invariant("cursor binding close lacks its original invocation"))?;if invocation.mode()!=crate::OriginalEffectCallbackMode::Receive{return Err(ValueError::invariant("cursor close is not its original receive invocation"))}if self.close_route.is_some(){return Err(ValueError::invariant("cursor has an unresolved original close invocation"))}let key=(invocation.identity(),2,body,None);let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=RetainedCloneBinding::close_into(&mut state.source,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
