 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.close_route.is_some_and(|(_,_,selected,_)|selected!=body){return Err(ValueError::invariant("cursor close query changed original body"))}if !self.closing{return Ok(Default::default())}if self.bytes.is_some(){self.close.next_owner_demands::<Vec<u8>>(true,&self.source,body)}else{self.close.next_owner_demands::<String>(self.output.is_some(),&self.source,body)}}
